"OLAYLAR_P0044:1840-01-01:0":{"b": ["لومړۍ عثماني کاغذي پیسې (قائمه) خپرې شوې", "d2e5e192"], "d": ["د تنظیماتو په لومړیو کلونو کې، کله چې د مالیې لپاره د عایداتو لټون روان و، د راتلونکي شیخ الاسلام عارف حکمت بېګ په وړاندیز د اسهام سیسټم پرمختللې بڼه، د قائمې کارونه، ومنل شوه. د ټولو 160,000 لیرو (32,000 کیسو) په ارزښت لومړنۍ قائمې، د نغدو پیسو د بېړنۍ اړتیا له امله، د چاپ انتظار پرته په لاسي لیکنه، د مالیې وزیر صائب پاشا په زمانه کې احتمالاً د 1840 په جون کې خپرې شوې. دا کاغذونه چې د نغدو پیسو حکم یې درلود، د ګردش موده یې اته کاله او کلنی ګټه یې 12.5% وه؛ ملاتړ یې نه درلود، یوازې ګټې ته یې د استانبول د ګمرک له عوایدو تضمین ښودل شوی و. خلکو دا نابلدې پیسې په ښه سترګه ونه کتلې او لاسي قائمې ژر د جعلکارانو هدف شوې.", "1f5f905c"]},
"OLAYLAR_P0047:1511-08-10:0":{"b": ["د پرتګالیانو له خوا د ملاکا نیول", "e1556746"], "d": ["په 1390مو لسیزو کې تأسیس شوې ملاکا د چین، هندوستان او لوېدیځ ترمنځ د سمندري سوداګرۍ په سیمه کې تر ټولو بوخت بندر او د ملاکا سلطنت مرکز و، او شاوخوا ټاپوګانو ته د اسلام د خپرېدو اصلي مرکز هم شوی و. پرتګالي افونسو د البوکرک د 1511 کال د اګست په 10 ښار ونیو؛ ښار لوټ شو، جوماتونه، د شاهي کورنۍ هدیرې او نورې پخې ودانۍ یې ړنګې کړل شوې ترڅو ډبرې یې د کلا په جوړولو کې وکارول شي. د پرتګالي ادارې لاندې ملاکا خپله پخوانۍ سوداګریزه برتري ونه ساتله؛ مسلمانو سوداګرو د سوماترا د اچې سلطنت بندر ته مخه کړه. پر اچې د ملاکا کې مېشتو پرتګالیانو له بریدونو وروسته د اچې سلطان علاءالدین رعایت شاه په 1565 کې له قانوني سلطان سلیمان مرسته وغوښته.", "bfb60150"]},
"OLAYLAR_P0048:1592-01-01:0":{"b": ["د لرستان حاکم شاهوېردي شاه عباس ته وفاداري اعلان کړه", "85791f94"], "d": ["د لرستان حاکم شاهوېردي، چې په 1589 کې یې عثمانیانو ته اطاعت کړی و او د بغداد بیګلربیګي تابع و، د صفوي مورخ اسکندر بېګ منشي د روایت له مخې په 1000 (1591-92) کال کې اړ شو چې صفوي تاج ته خپله وفاداري اعلان کړي. همدا سرچینه لیکي چې په دې کلونو کې به د دواړو لوریو ترمنځ تګ راتګ کاوه، د همدان والیان به یې ځورول او پر بروجرد یې چاپې کولې، او په 1002 (1593-94) کال کې شاه عباس خرم آباد اشغال کړ او ښار ته یې والي وټاکه. خو د TDV اسلامي دايرة المعارف صفویانو ته د لرستان بشپړ تړل، هغه لرستان چې د 1590 د استانبول تړون له مخې عثماني ادارې پورې تړل شوی و، 1603 کال ته ږدي. دواړه دودونه بېلې نېټې ورکوي؛ دا ماده په صفوي دود کې د وفادارۍ اعلان ښيي، د 1603 ماده قطعي له لاسه ورکول. په نقشه کې په دې مادې سره د مالک بدلون نشته: لرستان تر 1603 پورې د عثماني لوري ته ښکاري.", "d15b2c77"]},
"OLAYLAR_P0048:1603-01-01:0":{"b": ["لرستان په قطعي توګه صفویانو ته ولاړ", "4c5cf67b"], "d": ["هغه لرستان چې د 1590 د استانبول (فرهاد پاشا) تړون له مخې عثماني ادارې پورې تړل شوی و، شاه لومړي عباس په 1603 کې په بشپړه توګه صفویانو پورې وتړه. خو صفوي مورخ اسکندر بېګ منشي لیکي چې خرم آباد شاه عباس مخکې، په 1002 (1593-94) کال کې اشغال کړی و او ښار ته یې صفوي والي ټاکلی و؛ د دواړو دودونو ترمنځ دا توپیر نه دی حل شوی. په همدې کال د لرستان شمال ته عثماني کلا نهاوند هم د شاه عباس لاس ته ورغله؛ د همدان والي حسن خان کلا له خاورو سره برابره کړه.", "3e110da7"]},
"OLAYLAR_P0049:1303-09-01:0":{"b": ["د کتلان کمپني د بیزانس خدمت ته ننوته — د اناتولیا سفر پیل", "6623e7db"], "d": ["په لوېدیځه اناتولیا کې د ترکي بېګلکونو پر وړاندې خاوره له لاسه ورکوونکې بیزانسي امپراتورۍ د روجر دې فلور تر قوماندې لاندې شاوخوا 6500 کسیز کتلان ځواک د کرایي عسکرو په توګه خپل خدمت ته واخیست. د TDV د بیزانس مادې له مخې ځواک په 1303 کې د امپراتورۍ مرستې ته راغی او په راتلونکي کال یې د ګرمیان اوغلیانو محاصره کړی الاشهر وژغوره. خو کمپنۍ ژر پر هغو ځایونو لوټ پیل کړ چې ترې تېرېده؛ بیزانس هغه تراکیا ته تېره کړه او په 1305 کې یې روجر دې فلور ووژاوه.", "87b98a94"]},
