"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["د هابسبورګ پوځ له خوا د اورشووا نیول (د 1717 سفر)", "7a4faffe"], "d": ["د 1717 په سفر کې جنرال سپلېني د اګست په 27 اورشووا ته ورسېد او ښار یې په اسانۍ ونیو؛ په دې توګه هغه اورشووا چې مېرسي په 1716 کې نه وه نیولې، د هابسبورګ لاس ته ورغله. شاوخوا د ډانیوب د غاړې پېټکونه (د سربیا په لوري د ډېرداپ برخې په ګډون)، ځکه چې تر ټولو نږدې مېشتځي ټکي اورشووا پورې تړلي دي، د هغې د مالک په رنګ رنګول کېږي. نېټه یوازې د کال په توګه اخیستل شوې ده؛ دقیقه ورځ نه ده تایید شوې.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["د اورشووا پالانکا عثماني ته انتقال — د ساتونکي ادا قلعې ته شاتګ", "de759b16"], "d": ["د 1738 د سفر په پیل کې د ویدین ساتونکي حاجي محمد پاشا د ډانیوب په اوږدو کې پر اېرژیبېت مورچې برید وکړ. د می د 8 له غرمې وروسته د 4-5 زره کسیز سپاهي ټولګی د ډانیوب له کیڼې غاړې پر اورشووا مارچ وکړ او د اورشووا پر پالانکا یې برید وکړ؛ اتریشي ساتونکی، چې شاوخوا سل تلفات یې ورکړي وو، نوې اورشووا ته، یعنې د ادا قلعې ټاپو کلا ته، شاته شو. د جولای له مهادیې نښتو وروسته ادا قلعه هم د 1738 په اګست کې د عثماني لاس ته ورغله؛ د 1739 د بلغراد تړون وضعیت ومنه.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["دویم مراد الاجه حصار ونیو، نیش او شهرکوی عثماني ته ستانه شول", "54af926a"], "d": ["د سرب ډسپوټ ستېفان لازاریوویچ بې وارثه مرګ (1427) وروسته دویم مراد د یلدرم بایزید له سربي شهزادګۍ سره د واده په استناد ادعا وکړه چې د سربیا مشروع وارث دی، اقدام یې وکړ او الاجه حصار یې ونیو (1428). په همدې کال د لازاریوویچ له مرګ وروسته عثمانیانو د شهرکوی کلا هم بېرته واخیسته — ښار په 1412 کې ستېفان نیولی و او د موسی چلبي پر وړاندې یې دفاع شوې وه. د TDV د نیش مادې له مخې عثمانیانو نیش هم په همدې کال (831/1428) بېرته واخیست. په دې توګه د ستر موراوا او نیشاوا درې سره نښلوونکې کرښه د عثماني کنټرول لاندې راغله.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["صلیبي پوځ شهرکوی ونیو — د «اوږده سفر» د نیشاوا څانګه", "fdf6140c"], "d": ["د پاچا ولادیسلاو او د سرب ډسپوټ جوراج برانکوویچ په مشرۍ صلیبي پوځ په 1443 کې شهرکوی ونیو. د همدې سفر په دوام به عثماني ځواکونه په نومبر کې د ایزلادي په کوتل کې مات شي. شهرکوی د سېګېدین تړون (1444) وروسته دویم مراد بیا سربیانو ته ورکړ، خو په 1456 کې د جوراج برانکوویچ له مرګ وروسته عثمانیانو ته ولاړ.", "f56645a4"]},
